"use client";

import { type ReactNode, useRef, useState } from "react";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";

/**
 * An action that runs only after an explicit confirm. `details` shows exactly what will happen
 * (inputs, maximum price). The confirm fires once per opening: a double click never runs it twice.
 * It opens the dialog itself (no Trigger), so it works with every shadcn style, Radix or Base UI.
 */
export function ConfirmAction({
  label,
  title,
  description,
  details,
  confirmLabel = label,
  variant = "default",
  disabled,
  onConfirm,
}: {
  label: string;
  title: string;
  description: string;
  details?: ReactNode;
  confirmLabel?: string;
  variant?: "default" | "destructive" | "outline";
  disabled?: boolean;
  onConfirm: () => void | Promise<void>;
}) {
  const [open, setOpen] = useState(false);
  const fired = useRef(false);
  const button = useRef<HTMLButtonElement>(null);
  return (
    <>
      <Button
        ref={button}
        variant={variant}
        disabled={disabled}
        aria-haspopup="dialog"
        onClick={() => {
          fired.current = false;
          setOpen(true);
        }}
      >
        {label}
      </Button>
      <AlertDialog
        open={open}
        onOpenChange={(next: boolean) => {
          setOpen(next);
          // Back to the button that opened it, for keyboard users.
          if (!next) requestAnimationFrame(() => button.current?.focus());
        }}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>{title}</AlertDialogTitle>
            <AlertDialogDescription>{description}</AlertDialogDescription>
          </AlertDialogHeader>
          {details}
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              variant={variant === "outline" ? "default" : variant}
              onClick={() => {
                if (fired.current) return;
                fired.current = true;
                void onConfirm();
              }}
            >
              {confirmLabel}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

"use client";

import { useState } from "react";
import { fieldLabel, looksLikeId } from "@/lib/pramaan/plain";

/** A small control that copies an id to the clipboard without showing it. */
export function CopyReference({ value, label = "Copy reference" }: { value: string; label?: string }) {
  const [copied, setCopied] = useState(false);
  return (
    <button
      type="button"
      className="pr-link"
      aria-label={label}
      onClick={() => {
        void navigator.clipboard?.writeText(value);
        setCopied(true);
        setTimeout(() => setCopied(false), 2_000);
      }}
    >
      {copied ? "Copied" : label}
    </button>
  );
}

function Value({ value }: { value: unknown }) {
  if (value === null || value === undefined || value === "") return <>(empty)</>;
  if (typeof value === "boolean") return <>{value ? "Yes" : "No"}</>;
  if (looksLikeId(value)) return <CopyReference value={value} />;
  if (Array.isArray(value)) {
    if (value.every((v) => typeof v !== "object" || v === null)) return <>{value.map((v) => (looksLikeId(v) ? "a reference" : String(v))).join(", ")}</>;
    return (
      <ol className="space-y-2">
        {value.map((v, i) => (
          <li key={i}>{typeof v === "object" && v !== null ? <Fields input={v} nested /> : <Value value={v} />}</li>
        ))}
      </ol>
    );
  }
  if (typeof value === "object") return <Fields input={value} nested />;
  return <>{String(value)}</>;
}

function Fields({ input, nested = false, label }: { input: object; nested?: boolean; label?: string }) {
  const entries = Object.entries(input);
  return (
    <dl aria-label={label} className={nested ? "space-y-1 text-sm" : "pr-fields"}>
      {entries.map(([key, value]) => (
        <div key={key} className="pr-field">
          <dt>{fieldLabel(key)}</dt>
          <dd>
            <Value value={value} />
          </dd>
        </div>
      ))}
    </dl>
  );
}

/**
 * An object as plain labelled lines, exactly as it will be used or was returned: no JSON, no key
 * names, ids behind a Copy reference control. Nested objects and lists indent.
 */
export function InputFields({ input, label = "Details", empty = "No details were sent with this request." }: { input: unknown; label?: string; empty?: string }) {
  if (input === null || input === undefined || typeof input !== "object" || Object.keys(input).length === 0) {
    if (input !== null && input !== undefined && typeof input !== "object")
      return <p className="text-sm">{String(input)}</p>;
    return <p className="text-sm text-muted-foreground">{empty}</p>;
  }
  return <Fields input={input} label={label} />;
}

import "server-only";
import { PramaanError } from "@pramaan/sdk";
import { pramaan } from "@/lib/pramaan/server";

// Server half of the activity log: what ran, what it cost, and what failed with its next step.
//
// Per-call rows and webhook deliveries are not in the Pramaan API yet. The block asks for them
// (GET /v1/calls, GET /v1/calls/{id}, GET /v1/webhook-deliveries) and, when the API answers 404,
// falls back to the daily totals of GET /v1/usage, and hides the deliveries tab. When Pramaan adds
// the routes, the screen starts showing them with no change here.

export type CallStatus = "done" | "failed" | "running" | "waiting_approval";

export interface Call {
  /** The handle for one call. Never shown, only copied. */
  readonly call_id: string;
  readonly capability: string;
  readonly status: CallStatus;
  readonly charged_micro: number;
  readonly created_at: string;
  readonly error?: { readonly code: string; readonly message: string; readonly next?: string };
}

export interface DayRow {
  readonly day: string;
  readonly capability: string;
  readonly calls: number;
  readonly spend_micro: number;
}

export type ActivityPage =
  | { readonly mode: "calls"; readonly results: Call[]; readonly nextCursor?: string }
  | { readonly mode: "daily"; readonly results: DayRow[]; readonly nextCursor?: undefined };

export interface Delivery {
  readonly delivery_id: string;
  readonly event: string;
  readonly status: "delivered" | "failed" | "retrying";
  readonly attempts: number;
  readonly response_status?: number;
  readonly created_at: string;
  readonly error?: { readonly message: string; readonly next?: string };
}

export interface DeliveryList {
  /** False when the API has no delivery history: the tab is hidden. */
  readonly available: boolean;
  readonly results: Delivery[];
}

const bad = (message: string) => new PramaanError("invalid_request", message, { status: 400 });
const DAY = /^\d{4}-\d{2}-\d{2}$/;
const CAPABILITY = /^[a-z0-9][a-z0-9._-]{0,127}$/;
const STATUSES: readonly string[] = ["done", "failed", "running", "waiting_approval"];
const CALL_ID = /^[A-Za-z0-9_-]{1,128}$/;

/** A route the API doesn't have yet answers 404 with no body of its own. */
const missing = (e: unknown) => e instanceof PramaanError && e.status === 404;

export interface Filters {
  readonly capability?: string | null;
  readonly status?: string | null;
  readonly from?: string | null;
  readonly to?: string | null;
  readonly cursor?: string | null;
}

export async function listActivity(f: Filters): Promise<ActivityPage> {
  if (f.capability && !CAPABILITY.test(f.capability)) throw bad("Choose an action from the list.");
  if (f.status && !STATUSES.includes(f.status)) throw bad("Choose done, failed, running or waiting for a yes.");
  for (const d of [f.from, f.to]) if (d && !DAY.test(d)) throw bad("Dates look like 2026-10-31.");
  if (f.from && f.to && f.from > f.to) throw bad("The start date must come before the end date.");
  const q = new URLSearchParams();
  for (const [k, v] of Object.entries(f)) if (v) q.set(k, v);
  q.set("limit", "20");
  try {
    const page = await pramaan<{ results: Call[]; next_cursor?: string }>(`/v1/calls?${q}`);
    return { mode: "calls", results: page.results, ...(page.next_cursor ? { nextCursor: page.next_cursor } : {}) };
  } catch (e) {
    if (!missing(e)) throw e;
  }
  // Daily totals: per day and action, the only history the API keeps today. They can't show status.
  const to = f.to || new Date().toISOString().slice(0, 10);
  const from = f.from || new Date(Date.parse(`${to}T00:00:00Z`) - 29 * 86_400_000).toISOString().slice(0, 10);
  const usage = await pramaan<{ results: DayRow[] }>(`/v1/usage?from=${from}&to=${to}`);
  const rows = usage.results.filter((r) => !f.capability || r.capability === f.capability).sort((a, b) => b.day.localeCompare(a.day) || a.capability.localeCompare(b.capability));
  return { mode: "daily", results: rows };
}

export function getCall(id: string): Promise<Call> {
  if (!CALL_ID.test(id)) throw bad("That call isn't valid. Reload the list and try again.");
  return pramaan<Call>(`/v1/calls/${encodeURIComponent(id)}`);
}

export async function listDeliveries(): Promise<DeliveryList> {
  try {
    const r = await pramaan<{ results: Delivery[] }>("/v1/webhook-deliveries");
    return { available: true, results: r.results };
  } catch (e) {
    if (missing(e)) return { available: false, results: [] };
    throw e;
  }
}

"use client";

import { useCallback, useEffect, useId, useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { CopyReference } from "@/components/pramaan/fields";
import { type PillTone, StatusPill } from "@/components/pramaan/parts";
import { EmptyState, ErrorState, LoadingState } from "@/components/pramaan/states";
import { type ApiError, PRAMAAN_CHANGED, api, formatMicro, useResource } from "@/lib/pramaan/client";
import { actionName, formatDate, formatDay, humanize } from "@/lib/pramaan/plain";
import type { ActivityPage, Call, CallStatus, DeliveryList } from "@/lib/pramaan/activity";

const STATUS: Record<CallStatus, { text: string; tone: PillTone }> = {
  done: { text: "Done", tone: "green" },
  failed: { text: "Failed", tone: "red" },
  running: { text: "Running", tone: "blue" },
  waiting_approval: { text: "Waiting for a yes", tone: "amber" },
};

const DELIVERY: Record<string, { text: string; tone: PillTone }> = {
  delivered: { text: "Delivered", tone: "green" },
  failed: { text: "Failed", tone: "red" },
  retrying: { text: "Trying again", tone: "amber" },
};

interface Filters {
  capability: string;
  status: string;
  from: string;
  to: string;
}
const NONE: Filters = { capability: "", status: "", from: "", to: "" };

const query = (f: Filters, cursor?: string) => {
  const q = new URLSearchParams();
  for (const [k, v] of Object.entries({ ...f, cursor })) if (v) q.set(k, v);
  const s = q.toString();
  return `/api/pramaan/activity${s ? `?${s}` : ""}`;
};

/** One call: what ran, when, the cost, and for a failure what went wrong and what to do next. */
function CallDetail({ id }: { id: string }) {
  const c = useResource<Call>(`/api/pramaan/activity/${encodeURIComponent(id)}`);
  if (c.error && !c.data) return <ErrorState error={c.error} onRetry={c.reload} />;
  if (!c.data) return <LoadingState label="Loading this call" />;
  const d = c.data;
  const s = STATUS[d.status];
  return (
    <section aria-label="Call details" className="pr-card space-y-4">
      <div className="flex flex-wrap items-center gap-3">
        <h2>{actionName(d.capability)}</h2>
        <StatusPill tone={s.tone}>{s.text}</StatusPill>
      </div>
      <dl className="grid grid-cols-[auto_1fr] gap-x-4 gap-y-1 text-sm">
        <dt className="text-muted-foreground">When</dt>
        <dd>{formatDate(d.created_at)}</dd>
        <dt className="text-muted-foreground">Cost</dt>
        <dd>{d.status === "done" ? formatMicro(d.charged_micro) : d.status === "failed" ? "Nothing was charged" : "Not charged yet"}</dd>
        <dt className="text-muted-foreground">Reference</dt>
        <dd>
          <CopyReference value={d.call_id} />
        </dd>
      </dl>
      {d.error && (
        <div role="alert" className="space-y-2 rounded-md border border-destructive/50 p-3 text-sm">
          <p className="font-medium text-destructive">{d.error.message}</p>
          {d.error.next && (
            <p>
              <b>What to do next:</b> {d.error.next}
            </p>
          )}
        </div>
      )}
      {d.status === "waiting_approval" && <p className="text-sm text-muted-foreground">A person has to say yes in the approvals inbox before this runs.</p>}
    </section>
  );
}

/** A list that grows by "Show more" and starts over when the filters change. */
function useActivity(f: Filters) {
  const [state, setState] = useState<{ page?: ActivityPage; rows: ActivityPage["results"]; cursor?: string; error?: ApiError; loading: boolean }>({ rows: [], loading: true });
  const [tick, setTick] = useState(0);
  const key = JSON.stringify(f);
  const load = useCallback(
    async (cursor?: string) => {
      setState((s) => ({ ...s, loading: true }));
      try {
        const page = await api<ActivityPage>(query(JSON.parse(key) as Filters, cursor));
        setState((s) => ({ page, rows: cursor ? ([...s.rows, ...page.results] as ActivityPage["results"]) : page.results, cursor: page.nextCursor, loading: false }));
      } catch (e) {
        setState((s) => ({ ...s, error: e as ApiError, loading: false }));
      }
    },
    [key],
  );
  useEffect(() => {
    void load();
    const again = () => setTick((t) => t + 1);
    window.addEventListener(PRAMAAN_CHANGED, again);
    return () => window.removeEventListener(PRAMAAN_CHANGED, again);
  }, [load, tick]);
  return { ...state, more: () => load(state.cursor), reload: () => load() };
}

function Calls() {
  const id = useId();
  const [draft, setDraft] = useState<Filters>(NONE);
  const [applied, setApplied] = useState<Filters>(NONE);
  const [selected, setSelected] = useState<string>();
  const a = useActivity(applied);
  const daily = a.page?.mode === "daily";
  const options = [...new Set(["web.search", "email.send", "llm.complete", "sms.send", "web.read", ...a.rows.map((r) => r.capability)])].sort((x, y) => actionName(x).localeCompare(actionName(y)));
  const set = (patch: Partial<Filters>) => setDraft({ ...draft, ...patch });

  return (
    <div className="space-y-4">
      <form
        role="search"
        aria-label="Filter activity"
        className="flex flex-wrap items-end gap-3"
        onSubmit={(e) => {
          e.preventDefault();
          setSelected(undefined);
          setApplied(draft);
        }}
      >
        <div className="space-y-1.5">
          <Label htmlFor={`${id}-w`}>What ran</Label>
          <select id={`${id}-w`} className="pr-select" value={draft.capability} onChange={(e) => set({ capability: e.target.value })}>
            <option value="">Anything</option>
            {options.map((c) => (
              <option key={c} value={c}>
                {actionName(c)}
              </option>
            ))}
          </select>
        </div>
        {!daily && (
          <div className="space-y-1.5">
            <Label htmlFor={`${id}-s`}>How it went</Label>
            <select id={`${id}-s`} className="pr-select" value={draft.status} onChange={(e) => set({ status: e.target.value })}>
              <option value="">Any</option>
              {(Object.keys(STATUS) as CallStatus[]).map((k) => (
                <option key={k} value={k}>
                  {STATUS[k].text}
                </option>
              ))}
            </select>
          </div>
        )}
        <div className="space-y-1.5">
          <Label htmlFor={`${id}-f`}>From</Label>
          <Input id={`${id}-f`} type="date" value={draft.from} onChange={(e) => set({ from: e.target.value })} />
        </div>
        <div className="space-y-1.5">
          <Label htmlFor={`${id}-t`}>To</Label>
          <Input id={`${id}-t`} type="date" value={draft.to} onChange={(e) => set({ to: e.target.value })} />
        </div>
        <Button type="submit" variant="outline">
          Apply
        </Button>
        <Button type="button" variant="outline" onClick={() => { setDraft(NONE); setApplied(NONE); setSelected(undefined); }}>
          Clear
        </Button>
      </form>

      {a.error && a.rows.length === 0 ? (
        <ErrorState error={a.error} onRetry={a.reload} />
      ) : a.loading && a.rows.length === 0 ? (
        <LoadingState label="Loading activity" />
      ) : a.rows.length === 0 ? (
        <EmptyState title="Nothing ran in this period">Calls show up here once your app uses Pramaan. Try a wider range.</EmptyState>
      ) : daily ? (
        <div className="space-y-3">
          <p role="note" className="pr-sunk text-sm">Showing daily totals. A list of each call, with its status and what went wrong, isn't available yet.</p>
          <Table aria-label="Daily totals">
            <TableHeader>
              <TableRow>
                <TableHead>Day</TableHead>
                <TableHead>What ran</TableHead>
                <TableHead className="text-right">Calls</TableHead>
                <TableHead className="text-right">Cost</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {(a.rows as { day: string; capability: string; calls: number; spend_micro: number }[]).map((r) => (
                <TableRow key={r.day + r.capability}>
                  <TableCell>{formatDay(r.day)}</TableCell>
                  <TableCell>{actionName(r.capability)}</TableCell>
                  <TableCell className="text-right">{r.calls}</TableCell>
                  <TableCell className="text-right">{formatMicro(r.spend_micro)}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>
      ) : (
        <div className="grid gap-6 md:grid-cols-[minmax(0,1.2fr)_minmax(0,1fr)]">
          <div className="space-y-3">
            <ul className="pr-rows" aria-label="Calls">
              {(a.rows as Call[]).map((c) => {
                const s = STATUS[c.status];
                return (
                  <li key={c.call_id}>
                    <button type="button" className="pr-row" aria-pressed={selected === c.call_id} onClick={() => setSelected(c.call_id)}>
                      <span className="pr-row-main">
                        <b>{actionName(c.capability)}</b>
                        <span className="pr-row-sub">
                          {formatDate(c.created_at)}
                          {c.status === "done" ? ` · ${formatMicro(c.charged_micro)}` : ""}
                        </span>
                      </span>
                      <span className="pr-row-side">
                        <StatusPill tone={s.tone}>{s.text}</StatusPill>
                      </span>
                    </button>
                  </li>
                );
              })}
            </ul>
            {a.cursor && (
              <Button variant="outline" disabled={a.loading} onClick={a.more}>
                Show more
              </Button>
            )}
          </div>
          <div>{selected ? <CallDetail key={selected} id={selected} /> : <EmptyState title="Choose a call">What happened, and what to do next if it failed, shows here.</EmptyState>}</div>
        </div>
      )}
    </div>
  );
}

function Deliveries({ data }: { data: DeliveryList }) {
  if (data.results.length === 0) return <EmptyState title="No deliveries yet">Messages we send to your server show up here.</EmptyState>;
  return (
    <ul className="pr-rows" aria-label="Webhook deliveries">
      {data.results.map((d) => {
        const s = DELIVERY[d.status] ?? { text: humanize(d.status), tone: "grey" as const };
        return (
          <li key={d.delivery_id} className="pr-row">
            <span className="pr-row-main">
              <b>{humanize(d.event.replace(/[.]/g, " "))}</b>
              <span className="pr-row-sub">
                {formatDate(d.created_at)} · {d.attempts} {d.attempts === 1 ? "try" : "tries"}
                {d.response_status ? ` · your server answered ${d.response_status}` : ""}
              </span>
              {d.error && (
                <span className="pr-row-sub">
                  {d.error.message} {d.error.next && <b>What to do next: {d.error.next}</b>}
                </span>
              )}
            </span>
            <span className="pr-row-side">
              <StatusPill tone={s.tone}>{s.text}</StatusPill>
            </span>
          </li>
        );
      })}
    </ul>
  );
}

/**
 * What ran, what it cost, and what failed, with the next step. Filter by what ran, how it went and
 * the dates. Until the API lists each call it shows daily totals, and the webhook tab appears only
 * when the API has delivery history.
 */
export function ActivityLog() {
  const d = useResource<DeliveryList>("/api/pramaan/activity/deliveries");
  const hasDeliveries = d.data?.available === true;
  return (
    <Tabs defaultValue="calls">
      <TabsList>
        <TabsTrigger value="calls">Calls</TabsTrigger>
        {hasDeliveries && <TabsTrigger value="deliveries">Webhook deliveries</TabsTrigger>}
      </TabsList>
      <TabsContent value="calls" className="pt-4">
        <Calls />
      </TabsContent>
      {hasDeliveries && (
        <TabsContent value="deliveries" className="pt-4">
          <Deliveries data={d.data!} />
        </TabsContent>
      )}
    </Tabs>
  );
}

import { listActivity } from "@/lib/pramaan/activity";
import { connection } from "next/server";
import { errorResponse } from "@/lib/pramaan/server";

export async function GET(request: Request) {
  await connection();
  try {
    const q = new URL(request.url).searchParams;
    return Response.json(await listActivity({ capability: q.get("capability"), status: q.get("status"), from: q.get("from"), to: q.get("to"), cursor: q.get("cursor") }));
  } catch (error) {
    return errorResponse(error);
  }
}

import { getCall } from "@/lib/pramaan/activity";
import { errorResponse } from "@/lib/pramaan/server";

export async function GET(_request: Request, { params }: { params: Promise<{ id: string }> }) {
  try {
    return Response.json(await getCall((await params).id));
  } catch (error) {
    return errorResponse(error);
  }
}

import { listDeliveries } from "@/lib/pramaan/activity";
import { connection } from "next/server";
import { errorResponse } from "@/lib/pramaan/server";

export async function GET() {
  await connection();
  try {
    return Response.json(await listDeliveries());
  } catch (error) {
    return errorResponse(error);
  }
}
